+import java.util.Deque;
+import java.util.List;
+import java.util.concurrent.ConcurrentLinkedDeque;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Application-wide list of sent messages, so that it survives leaving and
+ * coming back to the contact view.
+ */
+@Service
+public class ContactMessageStore {
+
+    private final Deque<ContactMessage> messages = new ConcurrentLinkedDeque<>();
+
+    public void add(ContactMessage message) {
