+                new Button("Discard", e -> discardAndLeave()));
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setColspan(message, 2);
+        form.setWidthFull();
+
+        add(new H1("Contact"),
+                new RouterLink("About", AboutView.class),
+                form,
+                new HorizontalLayout(send),
+                grid,
+                leaveDialog);
+    }
+
+    private void sendIfEnabled() {
+        if (send.isEnabled()) {
+            send();
+        }
+    }
+
+    private void send() {
+        clearErrors();
+
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue().trim();
+
+        if (nameValue.isEmpty()) {
+            invalid(name, "Name is required");
+        }
+
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            invalid(email, "Enter a valid e-mail address");
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            invalid(email, "Give an e-mail address or a phone number");
+        }
+
+        if (message.getValue().length() > MAX_MESSAGE_LENGTH) {
+            invalid(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+        } else if (messageValue.isEmpty()) {
+            invalid(message, "Message is required");
+        }
+
+        if (isAnyInvalid()) {
+            return;
+        }
+
+        store.add(new ContactMessage(nameValue, emailValue, phoneValue, messageValue));
+        Notification.show("Message sent");
+
+        // Clearing the fields fires value change events that enable Send,
+        // so disable it afterwards.
+        inputs.forEach(HasValue::clear);
+        send.setEnabled(false);
+        refreshGrid();
+    }
+
+    private void refreshGrid() {
+        grid.setItems(store.newestFirst());
+    }
+
+    private void clearErrors() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private boolean isAnyInvalid() {
+        return name.isInvalid() || email.isInvalid() || message.isInvalid();
+    }
+
+    private static void invalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsavedInput()) {
+            pendingNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private boolean hasUnsavedInput() {
+        return inputs.stream().anyMatch(input -> !input.getValue().isEmpty());
+    }
+
+    private void keepEditing() {
+        leaveDialog.close();
+        pendingNavigation = null;
+    }
+
+    private void discardAndLeave() {
+        leaveDialog.close();
+        inputs.forEach(HasValue::clear);
+        BeforeLeaveEvent.ContinueNavigationAction navigation = pendingNavigation;
